//! Each class reads its items only from its own part of a Native
//! description, as C's loaders do through `astReadClassData` (channel.c):
//! an item placed in another class's part, between a different pair of
//! `IsA` lines, is ignored.
//!
//! `section_load_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/section_load_probe.c`: descriptions of Frames,
//! Mappings, Regions and a KeyMap that misplace an item, each with a
//! companion placing it where its class reads it, and a Polygon written
//! without the `Order` item older versions of AST omitted.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "section_load_oracle/cases.rs"]
mod cases;

use cases::V;
use starlink_ast::{AnyObject, from_native_string};

/// A year as astGetD gives it: Besselian before 1984 and Julian from then
/// on (frame.c `GetAttrib`), formatted to 15 significant digits by
/// `astFmtDecimalYr` and read back.
fn year(mjd: f64) -> V {
    let julian_1984 = 51544.5 + (1984.0 - 2000.0) * 365.25;
    let y = if mjd < julian_1984 {
        1900.0 + (mjd - 15019.81352) / 365.242198781
    } else {
        2000.0 + (mjd - 51544.5) / 365.25
    };
    V::Y(format!("{y:.14e}").parse().unwrap())
}

fn s(value: impl Into<String>) -> V {
    V::S(Box::leak(value.into().into_boxed_str()))
}

/// The attribute `name` of `obj`, as the probe reads it, with whether it is
/// set where the port can say.
fn attr(obj: &AnyObject, name: &str) -> (V, Option<bool>) {
    let (value, set) = match (name, obj) {
        ("Invert", _) => {
            let m = obj.as_mapping().expect("a Mapping");
            return (V::I(m.is_inverted().into()), None);
        }
        ("Zoom", AnyObject::ZoomMap(x)) => return (V::D(x.zoom()), None),
        ("Negated", _) => {
            let r = obj.as_region().expect("a Region");
            return (V::I(r.is_negated().into()), None);
        }
        ("SimpVertices", AnyObject::Polygon(x)) => {
            (V::I(x.simp_vertices().into()), x.test_simp_vertices())
        }
        ("SortBy", AnyObject::KeyMap(x)) => (s(format!("{:?}", x.sort_by())), x.test_sort_by()),
        ("Ident", _) if obj.as_frame().is_none() => {
            let m = obj.as_mapping().expect("a Mapping");
            (s(m.ident()), m.test_ident())
        }
        _ => frame_attr(obj, name),
    };
    (value, Some(set))
}

/// A Frame attribute `name` of `obj`.
fn frame_attr(obj: &AnyObject, name: &str) -> (V, bool) {
    let f = obj.as_frame().expect("a Frame");
    match (name, obj) {
        ("Ident", _) => (s(f.ident()), f.test_ident()),
        ("Title", _) => (s(f.title().unwrap()), f.test_title()),
        ("Digits", _) => (V::I(f.digits().into()), f.test_digits()),
        ("MinAxes", _) => (V::I(f.min_axes() as i64), f.test_min_axes()),
        ("MaxAxes", _) => (V::I(f.max_axes() as i64), f.test_max_axes()),
        ("Label(1)", _) => (s(f.label(1).unwrap()), f.test_label(1).unwrap()),
        ("Format(1)", _) => (s(f.format_str(1).unwrap()), f.test_format_str(1).unwrap()),
        ("StdOfRest", AnyObject::SpecFrame(x)) => {
            (s(x.std_of_rest().as_str()), x.test_std_of_rest())
        }
        ("SideBand", AnyObject::DSBSpecFrame(x)) => (s(x.sideband().as_str()), x.test_sideband()),
        ("TimeScale", AnyObject::TimeFrame(x)) => (s(x.timescale().as_str()), x.test_timescale()),
        ("System", AnyObject::SkyFrame(x)) => (s(x.system().as_str()), x.test_system()),
        ("Epoch", AnyObject::SkyFrame(x)) => (year(x.epoch_mjd()), x.test_epoch()),
        ("Equinox", AnyObject::SkyFrame(x)) => (year(x.equinox_mjd()), x.test_equinox()),
        _ => panic!("no Rust getter for {name} on this class"),
    }
}

#[test]
fn each_class_reads_only_its_own_part() {
    let mut failures = Vec::new();
    for &(name, text, attrs) in cases::CASES {
        let obj = from_native_string(&text.join("\n")).unwrap();
        for &(a, value, set) in attrs {
            let (got, got_set) = attr(&obj, a);
            if got != value || got_set.is_some_and(|g| g != set) {
                failures.push(format!(
                    "{name} {a}: got {:?}, C gives {:?}",
                    (got, got_set),
                    (value, set)
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
